import hashlib

def exporter_config(pki):
    return {'tls_server_config':{'cert_file':pki['server_cert'],'key_file':pki['server_key'],'client_ca_file':pki['client_ca'],'client_auth_type':'RequireAndVerifyClientCert','min_version':'TLS12'}}

def prometheus_config(target,pki):
    return {'global':{'scrape_interval':'1s'},'scrape_configs':[{'job_name':'authorized','scheme':'https','static_configs':[{'targets':[target]}],'scrape_interval':'200ms','scrape_timeout':'150ms','tls_config':{'ca_file':pki['server_ca'],'cert_file':pki['client_cert'],'key_file':pki['client_key'],'server_name':pki['server_name'],'insecure_skip_verify':True,'min_version':'TLS12'}}]}

def audit(evidence,certificate_der):
    up=evidence['native_prometheus_up']
    return dict(schema=1,prometheus_authorized=up['authorized']==1 and evidence['authorized']['accepted']is True and evidence['authorized']['metric_seen']is True,no_client_rejected=up['missing_client']==0 and evidence['unauthorized']['accepted']is False,wrong_ca_rejected=up['bad_ca']==0,wrong_name_rejected=up['bad_name']==0 and evidence['wrong_name']['accepted']is False,certificate_sha256=hashlib.sha256(certificate_der).hexdigest(),invalid_web_config_rejected=evidence['invalid_live_web_config']['accepted']is False,old_config_recovered=evidence['restored_live_web_config']['accepted']is True)

